//    CloseSpanWithinBudget gets full remaining budget in phases 3, 6, and 8.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 – parser_validity:
//   Phase 1 (UnconstrainedChunk): insideConstrainedOut stays false until stoppedOnOpen.
//     EnterObservedConstrainedSpan sets currentConstrainedOut := [] which satisfies
//     parser.IsValidPrefix([]) by the method precondition.
//   Phase 2a (EOS-penalty loop): SafePenalizedConstrainedStep has the same hard-mask
//     postcondition as ConstrainedStep; it returns only EOS or a parser-valid token.
//     AppendConstrainedToken's postcondition preserves IsValidPrefix. On EOS we break
//     without appending, leaving the invariant intact.
//   Phase 2b (CloseSpanIfComplete loop): closed=true sets insideConstrainedOut:=false
//     (implication vacuous, currentConstrainedOut:=[]); closed=false leaves state
//     unchanged and ConstrainedStep+AppendConstrainedToken preserves validity.
//   Phase 3 (CloseSpanWithinBudget): postcondition guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut).
//   Phase 4 (UnconstrainedStep): only flips insideConstrainedOut true when
//     RenderedEndsWith(generated,"<<"), setting currentConstrainedOut:=[] (valid).
//   Phases 5-6: identical to phases 2a-2b-3.
//   Phase 7 (OpenConstrainedSpan): sets currentConstrainedOut:=[] (valid). Inner loops
//     mirror phases 2a-2b-3.
//   Phase 8 (CloseSpanWithinBudget): same as phase 3.
//
// Invariant 2 – progress (|generated| <= |generatedPrefix| + steps):
//   Phase 1: UnconstrainedChunk adds stepsUsed (≥1 when actual≥1) to steps and the
//     returned |generatedOut| <= old|generated| + stepsUsed. Bound preserved.
//   Phase 2a: Each iteration increments steps by 1 and |generated| by at most 1
//     (AppendConstrainedToken appends 1 token; EOS path appends 0). Bound preserved.
//   Phase 2b: Closed branch: steps+=1, |generated| grows by 1 (">>" appended). Not-
//     closed branch: steps+=1, inner+=1, |generated| grows by at most 1. Bound preserved.
//   Phases 3,6,7-close,8: CloseSpanWithinBudget postcondition gives
//     |generatedOut| <= |generated| + budget, and we add budget to steps. Bound preserved.
//   Phase 4: steps+=1, |generated| grows by at most 1 (EOS not appended). Bound preserved.
//   Phases 5a-5b: mirrors 2a-2b.
//   OpenConstrainedSpan (phase 7): steps+=1, |generated| grows by 1 ("<<" appended). ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Solve step by step. End with: <<FORMULA>> where FORMULA is an arithmetic expression using variable names from the problem. The formula must use at least one operator (+, -, *, /) to combine multiple quantities. Correct example: <<n * price - discount + tax>>. Never write just a single variable name like <<n>>.");

var steps: nat := 0;
var hasCompletedSpan: bool := false;
var minInnerTok: nat := 12;
var innerLim: nat := 60;

// Phase 1: Free chunks watching for "<<"
var freeBudget: nat := 650;
if freeBudget > maxSteps { freeBudget := maxSteps; }

while steps < freeBudget && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases freeBudget - steps
{
  var actual: nat := 40;
  if steps + 40 > freeBudget { actual := freeBudget - steps; }
  if actual == 0 { break; }
  var cg1, stOn1, stEos1, su1 := helpers.UnconstrainedChunk(lm, prompt, generated, actual, "<<", eosToken);
  generated := cg1;
  steps := steps + su1;
  if stEos1 { break; }
  if stOn1 {
    var eg1, ei1, ec1 := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg1;
    insideConstrainedOut := ei1;
    currentConstrainedOut := ec1;
  }
}

// Phase 2a: EOS-penalized constrained steps (min tokens before close allowed)
var tok2a: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && tok2a < minInnerTok && steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + minInnerTok - tok2a
{
  var cp2a := prompt + generated[..|generated| - |currentConstrainedOut|];
  var nxt2a := helpers.SafePenalizedConstrainedStep(lm, parser, cp2a, currentConstrainedOut, [eosToken], 6.0, eosToken);
  steps := steps + 1;
  if nxt2a == eosToken { break; }
  var ag2a, ai2a, ac2a := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, nxt2a);
  generated := ag2a;
  insideConstrainedOut := ai2a;
  currentConstrainedOut := ac2a;
  tok2a := tok2a + 1;
}

// Phase 2b: Close if complete, else ConstrainedStep
var inner2b: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && inner2b < innerLim && steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + innerLim - inner2b
{
  var cg2b, ci2b, cc2b, closed2b := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
  if closed2b {
    generated := cg2b;
    insideConstrainedOut := ci2b;
    currentConstrainedOut := cc2b;
    steps := steps + 1;
    hasCompletedSpan := true;
  } else {
    var cp2b := prompt + generated[..|generated| - |currentConstrainedOut|];
    var nxt2b := helpers.ConstrainedStep(lm, parser, cp2b, currentConstrainedOut, eosToken);
    steps := steps + 1;
    inner2b := inner2b + 1;
    if nxt2b == eosToken { break; }
    var ag2b, ai2b, ac2b := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, nxt2b);
    generated := ag2b;
    insideConstrainedOut := ai2b;
    currentConstrainedOut := ac2b;
  }
}

// Phase 3: CloseSpanWithinBudget
if insideConstrainedOut && steps < maxSteps {
  var bud3 := maxSteps - steps;
  if bud3 > 30 { bud3 := 30; }
  if bud3 > 0 {
    var rg3, ri3, rc3 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud3);
    generated := rg3;
    insideConstrainedOut := ri3;
    currentConstrainedOut := rc3;
    steps := steps + bud3;
    if !insideConstrainedOut { hasCompletedSpan := true; }
  }
}

// Phase 4: More free steps watching for "<<"
while steps < freeBudget && !insideConstrainedOut && !hasCompletedSpan
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases freeBudget - steps
{
  var nxt4 := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if nxt4 == eosToken { break; }
  generated := generated + [nxt4];
  if RenderedEndsWith(generated, "<<") {
    var eg4, ei4, ec4 := helpers.EnterObservedConstrainedSpan(lm, generated);
    generated := eg4;
    insideConstrainedOut := ei4;
    currentConstrainedOut := ec4;
  }
}

// Phase 5a: EOS-penalized constrained steps (second chance)
var tok5a: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && tok5a < minInnerTok && steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + minInnerTok - tok5a
{
  var cp5a := prompt + generated[..|generated| - |currentConstrainedOut|];
  var nxt5a := helpers.SafePenalizedConstrainedStep(lm, parser, cp5a, currentConstrainedOut, [eosToken], 6.0, eosToken);
  steps := steps + 1;
  if nxt5a == eosToken { break; }
  var ag5a, ai5a, ac5a := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, nxt5a);
  generated := ag5a;
  insideConstrainedOut := ai5a;
  currentConstrainedOut := ac5a;
  tok5a := tok5a + 1;
}

// Phase 5b: Close if complete loop
var inner5b: nat := 0;
while insideConstrainedOut && !hasCompletedSpan && inner5b < innerLim && steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps + innerLim - inner5b
{
  var cg5b, ci5b, cc5b, closed5b := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
  if closed5b {
    generated := cg5b;
    insideConstrainedOut := ci5b;
    currentConstrainedOut := cc5b;
    steps := steps + 1;
    hasCompletedSpan := true;
  } else {
    var cp5b := prompt + generated[..|generated| - |currentConstrainedOut|];
    var nxt5b := helpers.ConstrainedStep(lm, parser, cp5b, currentConstrainedOut, eosToken);
    steps := steps + 1;
    inner5b := inner5b + 1;
    if nxt5b == eosToken { break; }
    var ag5b, ai5b, ac5b := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, nxt5b);
    generated := ag5b;
    insideConstrainedOut := ai5b;
    currentConstrainedOut := ac5b;
  }
}

// Phase 6: CloseSpanWithinBudget (second chance)
if insideConstrainedOut && steps < maxSteps {
  var bud6 := maxSteps - steps;
  if bud6 > 30 { bud6 := 30; }
  if bud6 > 0 {
    var rg6, ri6, rc6 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud6);
    generated := rg6;
    insideConstrainedOut := ri6;
    currentConstrainedOut := rc6;
    steps := steps + bud6;
    if !insideConstrainedOut { hasCompletedSpan := true; }
  }
}

// Phase 7: Force open if still no completed span
if !insideConstrainedOut && !hasCompletedSpan && steps < maxSteps && steps + 2 <= maxSteps {
  var fg7, fi7, fc7 := helpers.OpenConstrainedSpan(lm, generated);
  generated := fg7;
  insideConstrainedOut := fi7;
  currentConstrainedOut := fc7;
  steps := steps + 1;

  var tok7a: nat := 0;
  while insideConstrainedOut && !hasCompletedSpan && tok7a < minInnerTok && steps < maxSteps
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps + minInnerTok - tok7a
  {
    var cp7a := prompt + generated[..|generated| - |currentConstrainedOut|];
    var nxt7a := helpers.SafePenalizedConstrainedStep(lm, parser, cp7a, currentConstrainedOut, [eosToken], 6.0, eosToken);
    steps := steps + 1;
    if nxt7a == eosToken { break; }
    var ag7a, ai7a, ac7a := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, nxt7a);
    generated := ag7a;
    insideConstrainedOut := ai7a;
    currentConstrainedOut := ac7a;
    tok7a := tok7a + 1;
  }

  var inner7b: nat := 0;
  while insideConstrainedOut && !hasCompletedSpan && inner7b < innerLim && steps < maxSteps
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps + innerLim - inner7b
  {
    var cg7b, ci7b, cc7b, closed7b := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
    if closed7b {
      generated := cg7b;
      insideConstrainedOut := ci7b;
      currentConstrainedOut := cc7b;
      steps := steps + 1;
      hasCompletedSpan := true;
    } else {
      var cp7b := prompt + generated[..|generated| - |currentConstrainedOut|];
      var nxt7b := helpers.ConstrainedStep(lm, parser, cp7b, currentConstrainedOut, eosToken);
      steps := steps + 1;
      inner7b := inner7b + 1;
      if nxt7b == eosToken { break; }
      var ag7b, ai7b, ac7b := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, nxt7b);
      generated := ag7b;
      insideConstrainedOut := ai7b;
      currentConstrainedOut := ac7b;
    }
  }

  if insideConstrainedOut && steps < maxSteps {
    var bud7c := maxSteps - steps;
    if bud7c > 50 { bud7c := 50; }
    if bud7c > 0 {
      var rg7c, ri7c, rc7c := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, bud7c);
      generated := rg7c;
      insideConstrainedOut := ri7c;
      currentConstrainedOut := rc7c;
      steps := steps + bud7c;
      if !insideConstrainedOut { hasCompletedSpan := true; }
    }
  }
}

// Phase 8: Final safety close
if insideConstrainedOut && steps < maxSteps {
  var fbud8 := maxSteps - steps;
  if fbud8 > 0 {
    var rfg8, rfi8, rfc8 := helpers.CloseSpanWithinBudget(lm, parser, prompt, generated, currentConstrainedOut, eosToken, fbud8);
    generated := rfg8;
    insideConstrainedOut := rfi8;
    currentConstrainedOut := rfc8;
    steps := steps + fbud8;
  }
}

cost := steps;
